#include <stdio.h>

int main(void) {
    int n, venta, max_venta;
    scanf("%d", &n);
    scanf("%d", &max_venta);
    for (int i = 1; i < n; i++) {
        scanf("%d", &venta);
        if (venta > max_venta) {
            max_venta = venta;
        }
    }
    printf("%.1f\n", (float)max_venta);
    return 0;
}
